def is_active_to_status(apps: Apps, schema_editor: BaseDatabaseSchemaEditor) -> None:
    """Active Consultancies become Active; deactivated ones Terminated, hosts switched off.

    Public schema only, one row per Consultancy.
    """
    Consultancy = apps.get_model("tenancy", "Consultancy")
    Domain = apps.get_model("tenancy", "Domain")
    now = django.utils.timezone.now()
    Consultancy.objects.filter(is_active=True).update(status="active")
    Consultancy.objects.filter(is_active=False).update(status="terminated", terminated_at=now)
    Domain.objects.filter(tenant__is_active=False).update(is_active=False)


def status_to_is_active(apps: Apps, schema_editor: BaseDatabaseSchemaEditor) -> None:
    Consultancy = apps.get_model("tenancy", "Consultancy")
    Consultancy.objects.exclude(status="terminated").update(is_active=True)
    Consultancy.objects.filter(status="terminated").update(is_active=False)


